def promedio(notas):
    return sum(notas) / len(notas)

notas = []
while True:
    texto = input("Nota (o 'fin'): ")
    if texto == "fin":
        break
    notas.append(float(texto))

if notas:
    print(f"Promedio: {promedio(notas):.1f}")
else:
    print("No cargaste notas")
